INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3214, '問', 'Mon', 'Bertanya, masalah, mempertanyakan', '口', 'モン', 'と（う）、と（い）', 'Bertanya, mempertanyakan, menanyakan, atau mempermasalahkan sesuatu (Kanji Pedia)', false, 'border-l-4 border-tertiary', 555);
INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3215, '題', 'Dai', 'Topik, judul, tema, masalah, soal', '頁 (Oogai/Kepala, halaman)', 'ダイ', '-', 'Topik, judul, tema, dan pokok bahasan yang menjadi objek pembicaraan atau pembelajaran (Kanji Pedia)', false, 'border-l-4 border-primary', 555);
INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3216, '答', 'Tou', 'Menjawab, membalas, merespon', '竹 (Takekanmuri) Radikal Bambu', 'トウ', 'こた（える）', 'Memberikan jawaban, memberikan respons, atau menyampaikan balasan terhadap suatu pertanyaan maupun permintaan.', false, 'border-l-4 border-secondary', 555);
INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3217, '点', 'Ten', 'Titik, poin, tanda, skor/nilai, fokus spesifik', '黑 (Kuro / Hitam)', 'テン', 'つ（く）、つ（ける）', 'Penilaian, titik lokasi, sudut pandang, atau poin penting dalam evaluasi (Kanji Pedia)', false, 'border-l-4 border-tertiary', 555);
INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3218, '研', 'Ken', 'Mengasah; meneliti', '石（いし・へん）', 'ケン', 'と.ぐ', 'Mengasah, mempelajari, atau meneliti sesuatu secara mendalam agar mendapatkan pengetahuan dan pemahaman yang baik. (Kanjigen)', false, 'border-l-4 border-primary', 556);
