INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3221, '調', 'Chou / Shiraberu', 'Memeriksa', '言 (ごんべん)', 'チョウ', 'しらべる, ととのえる, ととのう', 'Menyelidiki atau memeriksa sesuatu dengan teliti, serta mengatur sesuatu agar menjadi benar. (Kanjigen)', false, 'border-purple-500', 556);
INSERT INTO `Kanji` (`id`, `character`, `romaji`, `meaning`, `bushuu`, `onyomi`, `kunyomi`, `baseMeaning`, `isJukugo`, `border`, `moduleId`) VALUES (3222, '査', 'Sa', 'Memeriksa, menyelidiki, menginspeksi', '木 (きへん)', 'サ', '-', 'Mengatur berbagai hal dan membawanya ke dalam keadaan seimbang, melakukan pemeriksaan secara teliti terhadap sebuah objek, data dan keadaan untuk memastikan kondisi yang sebenarnya. (https://kanji.me/hitsujun)', false, 'border-emerald-500', 556);
