INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12960, 3212, 15061, 'Hubungan makna antara kanji試dan 験menjadi試験 menunjukan gabungan kedua kanji tersebut membentuk sebuah makna "suatu kegiatan untuk mengukur pengetahuan atau kemampuan seseorang, maka ketika digabungkan mengandung makna ujian".');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12961, 3212, 15062, 'Hubungan makna  antara kanji 入 dan 試 menjadi 入試 , menunjukan gabungan kedua kanji tersebut membentuk sebuah makna “untuk masuk sekolah atau pun  perguruan “tinggi harus melalui ujian’.');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12962, 3212, 15063, 'Hubungan makna antar kanji 試 dan 問 menjadi 試問, menunjukan gabungan kedua kanji tersebut membentuk sebuah makna " ujian dilakukan dengan tanya jawab secara langsung".');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12963, 3212, 15064, 'Hubungan makna antar kanji 試  dan 着 menjadi 試着, menunjukan gabungan kedua kanji tersebut membentuk  sebuah makna  "mencoba pakaian sebelum memutuskan untuk memberlinya".');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12964, 3212, 15065, 'Hubungan makna antar kanji 試 dan 用 menunjukan gabungan kedua kanji tersebut　membentuk sebuah makna "bahwa untuk mengetahui manfaat  atau kualitasnya harus menggunakan sesuatu"');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (12965, 3212, 15066, 'Hubungan makna antar kanji 試 dan 乗 menunjukan bahwa sebelum membeli atau menggunakan kendaraan harus mencoba kendaraan terlebih dahulu.');
