INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13050, 3218, 15150, 'Hubungan makna antar kanji 研・究・会 menjadi 研究会, menunjukkan bahwa gabungan ketiga kanji tersebut membentuk makna "forum atau kelompok yang berkumpul untuk berdiskusi dan melakukan penelitian bersama".');
