INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13070, 3219, 15170, 'Hubungan makna antar kanji 研・究・書 menjadi 研究書, menunjukkan bahwa gabungan ketiga kanji tersebut membentuk makna "buku yang memuat hasil penelitian atau kajian ilmiah secara mendalam."');
