INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13073, 3219, 15173, 'Hubungan makna antar kanji 学・究・心 menjadi 学究心, menunjukkan bahwa gabungan ketiga kanji tersebut membentuk makna "semangat yang tinggi untuk mempelajari dan mendalami ilmu pengetahuan."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13074, 3219, NULL, 'Hubungan makna antar kanji 追 dan 究 menjadi 追究, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna "terus mencari dan menyelidiki suatu hal hingga diperoleh penjelasan yang memadai."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13075, 3219, 15174, 'Hubungan makna antara 深く dan 究める menunjukkan bahwa kegiatan tersebut bermakna "mempelajari atau menyelidiki sesuatu secara sungguh-sungguh hingga mencapai tingkat pemahaman yang mendalam."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13076, 3219, NULL, 'Hubungan makna antar kanji 究 dan 極 menjadi 究極, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna "tingkat tertinggi atau hasil akhir yang dicapai setelah melalui proses pencarian dan pendalaman."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13077, 3219, 15163, 'Hubungan makna antar kanji 究 dan 理 menjadi 究理, menunjukkan bahwa gabungan kedua kanji tersebut membentuk makna "pemahaman terhadap prinsip atau hakikat suatu hal yang diperoleh melalui penyelidikan mendalam."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13078, 3219, NULL, 'Hubungan makna antara 結論 dan 究明 menjadi 結論究明, menunjukkan bahwa gabungan tersebut membentuk makna "proses penyelidikan yang dilakukan hingga menghasilkan kesimpulan yang dapat dipertanggungjawabkan."');
INSERT INTO `SemanticRelation` (`id`, `kanjiId`, `jukugoId`, `penjelasan`) VALUES (13079, 3219, NULL, 'Hubungan makna antara 本質 dan 究明 menjadi 本質究明, menunjukkan bahwa gabungan tersebut membentuk makna "penyelidikan yang bertujuan menemukan esensi atau hakikat sebenarnya dari suatu objek atau peristiwa."');
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6939, 3213, '明日の試験はとても難しいですから、頑張ってください。', 'Ashita no shiken wa totemo muzukashii desu kara, ganbatte kudasai.', 'Karena ujian besok sangat sulit, berjuanglah.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6940, 3213, '日本の大学の入学試験のために、毎日5時間勉強しています。', 'Nihon no daigaku no nyuugaku shiken no tame ni, mainichi gojikan benkyou shiteimasu.', 'Demi ujian masuk universitas Jepang, saya belajar 5 jam setiap hari.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6941, 3213, '卒業するために、来月面接試験を受けます。', 'Sotsugyou suru tame ni, raigetsu mensetsu shiken wo ukemasu.', 'Untuk lulus, saya akan mengikuti ujian wawancara bulan depan.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6942, 3213, '日本へ留学したことは、私にとって良い経験になりました。', 'Nihon he ryuugaku shita koto wa, watashi ni totte yoi keiken ni narimashita.', 'Belajar di Jepang telah menjadi pengalaman yang baik bagi saya.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6943, 3213, '化学の授業で, 水の性質を調べる実験を行いました。', 'Kagaku no jugyou de, mizu no seishitsu wo shiraberu jikken wo okonaimashita.', 'Dalam kelas kimia, kami melakukan eksperimen untuk memeriksa sifat-sifat air.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6944, 3214, 'この問題は少し難しいです。', 'Kono mondai wa sukoshi muzukashii desu.', 'Soal ini sedikit sulit.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6945, 3214, '先生に質問してください。', 'Sensei ni shitsumon shitekudasai.', 'Silakan bertanya kepada guru.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6946, 3214, '日本では環境問題が重要です。', 'Nihon dewa kankyou mondai ga juuyou desu.', 'Di Jepang, masalah lingkungan adalah hal yang penting.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6947, 3214, 'この問題集で勉強します。', 'Kono mondaishuu de benkyou shimasu.', 'Saya belajar menggunakan buku kumpulan soal ini.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6948, 3214, '電話で問い合わせをしました。', 'Denwa de toiawase wo shimashita.', 'Saya mengajukan pertanyaan via telepon.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6949, 3215, '宿題が多すぎて、昨日は寝る時間がありませんでした。', 'Shukudai ga oosugite, kinou wa neru jikan ga arimasen deshita.', 'Karena PR terlalu banyak, kemarin saya tidak punya waktu tidur.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6950, 3215, '今日のゼミでは、卒業論文の論題について議論します。', 'Kyou no zemi dewa, sotsugyou ronbun no rondai ni tsuite giron shimasu.', 'Di seminar hari ini, kami akan mendiskusikan tema tesis kelulusan.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6951, 3215, '面接試験では、最近の時事問題について質問されました。', 'Mensetsu shiken dewa, saikin no jiji mondai ni tsuite shitsumon saremashita.', 'Dalam ujian wawancara, saya ditanya tentang isu-isu aktual baru-baru ini.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6952, 3215, '彼女は自分の留学経験を題材にして小説を書きました。', 'Kanojo wa jibun no ryuugaku keiken wo daizai ni shite shousetsu wo kakimashita.', 'Dia menulis novel berdasarkan pengalaman belajarnya di luar negeri.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6953, 3215, '今週は課題がたくさんありますから、とても忙しいです。', 'Konshuu wa kadai ga takusan arimasu kara, totemo isogashii desu.', 'Karena minggu ini ada banyak tugas, saya sangat sibuk.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6954, 3216, '先生の質問に答えました。', 'Sensei no shitsumon ni kotaemashita.', 'Saya menjawab pertanyaan guru.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6955, 3216, '正しい答えを書いてください。', 'Tadashii kotae wo kaite kudasai.', 'Silakan tulis jawaban yang benar.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6956, 3216, '回答をメールで送りました。', 'Kaitou wo meeru de okurimashita.', 'Saya mengirimkan jawaban melalui email.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6957, 3216, '応答はなかなかありません。', 'Outou wa naka naka arimasen.', 'Responnya tidak kunjung datang.', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6958, 3216, '一問一答はどういう意味ですか。', 'Ichimon ittou wa dou iu imi desu ka.', 'Apa arti dari ''satu pertanyaan satu jawaban''?', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (6959, 3217, '先生はテストを採点しました。', 'Sensei wa tesuto wo saiten shimashita.', 'Guru menilai ujian tersebut.', true);
