INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7095, 3283, '供給について勉強します。', '供給 ni tsuite benkyou shimasu.', 'Belajar tentang 供給 (Penawaran / Supply).', true);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7096, 3212, '来週、日本語の試験がありますから、今晩から準備します。', 'Raishuu, nihongo no shiken ga arimasu kara, konban kara junbi shimasu.', 'Karena minggu depan ada ujian bahasa Jepang, saya akan bersiap-siap mulai malam ini.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7097, 3212, '服を買う前に、お店のここで試着することができます。', 'Fuku wo kau mae ni, omise no koko de shichaku suru koto ga dekimasu.', 'Sebelum membeli pakaian, Anda dapat mencobanya di bagian toko ini.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7098, 3212, 'この新しいアプリは、1か月無料で試用できます。', 'Kono atarashii apuri wa, ikkagetsu muryou de shiyou dekimasu.', 'Aplikasi baru ini dapat dicoba secara gratis selama 1 bulan.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7099, 3212, 'デパ地下で新しいケーキの試食をしました。', 'Depachika de atarashii keeki no shishoku wo shimashita.', 'Saya mencicipi kue baru di lantai bawah tanah department store.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7100, 3212, '新しいジュースの試飲をお客さんにしてもらいます。', 'Atarashii juusu no shiin wo okyakusan ni shitemoraimasu.', 'Kami meminta pelanggan untuk mencicipi jus baru.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7101, 3218, '研究室の テーブルに 新しい パソコンが おいてあります。', 'Kenkyuushitsu no teeburu ni atarashii pasokon ga oite arimasu.', 'Di meja ruang penelitian ada komputer baru yang diletakkan.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7102, 3218, '研修生は 先生の 話を 聞きながら メモを とります。', 'Kenshuusei wa sensei no hanashi o kikanagara memo o torimasu.', 'Peserta pelatihan mencatat sambil mendengarkan penjelasan guru.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7103, 3218, 'あの 研究者は 毎日 10時間 勉強するんです。', 'Ano kenkyuusha wa mainichi juujikan benkyou suru ndesu.', 'Peneliti itu belajar selama 10 jam setiap hari.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7104, 3218, '来月の 研修旅行の チケットを 買って おきます。', 'Raigetsu no kenshuuryokou no chiketto o katte okimasu.', 'Saya akan membeli tiket perjalanan studi bulan depan terlebih dahulu.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7105, 3218, '図書室で いい 研究方法が 見つかりました。', 'Toshoshitsu de ii kenkyuuhouhou ga mitsukarimashita.', 'Metode penelitian yang bagus telah ditemukan di ruang perpustakaan.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7106, 3219, '来年 大学の 研究科に 入ろうと 思っています。', 'Rainen daigaku no kenkyuuka ni hairou to omotte imasu.', 'Tahun depan saya berencana masuk ke program pascasarjana (program riset) universitas.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7107, 3219, '明日 先生の 研究室に 行くんです。', 'Ashita sensei no kenkyuushitsu ni ikun desu.', 'Besok saya akan pergi ke ruang laboratorium/penelitian profesor.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7108, 3219, '本を 読みながら 新しい 研究方法を 考えます。', 'Hon wo yominagara atarashii kenkyuuhouhou wo kangaemasu.', 'Sambil membaca buku, saya memikirkan metode penelitian yang baru.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7109, 3219, '会議の 前に 事故の 原因究明を して おきます。', 'Kaigi no mae ni jiko no gen''inkyuumei wo shite okimasu.', 'Sebelum rapat, saya akan melakukan penyelidikan penyebab kecelakaan terlebih dahulu.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7110, 3219, 'あの 学生は 強い 探究心を 持って います。', 'Ano gakusei wa tsuyoi tankyuushin wo motte imasu.', 'Siswa itu memiliki rasa ingin tahu / semangat penyelidikan yang kuat.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7111, 3220, '明日の 朝 8時に 駅に 集合しようと 思っています。', 'Ashita no asa hachiji ni eki ni shuugou shiyou to omotte imasu.', 'Saya berencana berkumpul di stasiun jam 8 besok pagi.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7112, 3220, '静かな 部屋の ほうが 勉強に 集中できるんです。', 'Shizuka na heya no hou ga benkyou ni shuuchuu dekiru n desu.', 'Di ruangan yang tenang saya bisa lebih berkonsentrasi belajar.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7113, 3220, '机の 上に 新しい 日本の 写真集が おいてあります。', 'Tsukue no ue ni atarashii nihon no shashinshuu ga oite arimasu.', 'Di atas meja ditaruh album foto Jepang yang baru.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7114, 3220, '音楽を 聞きながら N4の 問題集を やります。', 'Ongaku wo kikinagara N4 no mondaishuu wo yarimasu.', 'Sambil mendengarkan musik, saya mengerjakan buku latihan soal N4.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7115, 3220, '旅行の 前に インターネットで 情報収集を して おきます。', 'Ryokou no mae ni intaanetto de jouhoushuushuu wo shite okimasu.', 'Sebelum berwisata, saya mengumpulkan informasi lewat internet terlebih dahulu.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7116, 3221, '体調が 悪い ときは、無理を しない ほうが いいです。', 'Taichou ga warui toki wa, muri wo shinai hou ga ii desu.', 'Saat kondisi tubuh buruk, sebaiknya jangan memaksakan diri.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7117, 3221, 'ラジオを 聞きながら 野菜を 調理します。', 'Rajio wo kikinagara yasai wo chouri shimasu.', 'Sambil mendengarkan radio, saya memasak sayuran.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7118, 3221, 'インターネットで 辞書の 意味を 調べようと 思っています。', 'Intaanetto de jisho no imi wo shirabeyou to omotte imasu.', 'Saya berencana mencari arti kamus lewat internet.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7119, 3221, 'パソコンの 調子が 悪いですから、不調に なるかもしれません。', 'Pasokon no choushi ga warui desu kara, fuchou ni naru kamo shiremasen.', 'Karena kondisi laptop buruk, mungkin sedang bermasalah.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7120, 3221, '先生は 大事な ポイントを 強調するんです。', 'Sensei wa daiji na pointo wo kyouchou suru n desu.', 'Guru menegaskan poin-poin yang penting.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7121, 3222, '私は日本語教育を調査したほうがいいと思います。', 'Watashi wa nihongo kyouiku wo chousa shita hou ga ii to omoimasu.', 'Menurut saya sebaiknya meneliti tentang pendidikan bahasa Jepang.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7122, 3222, '先生は「もう一度調査してください」と言いました。', 'Sensei wa "mou ichido chousa shite kudasai" to iimashita.', 'Guru berkata, "Tolong lakukan penelitian sekali lagi."', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7123, 3222, '私は卒業論文で市場調査をしたいと思っています。', 'Watashi wa sutsugyou ronbun de shijouchousa wo shitai to omotte imasu.', 'Saya ingin melakukan riset pasar untuk skripsi saya.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7124, 3222, '明日、検査の結果が出るでしょう。', 'Ashita, kensa no kekka ga deru deshou.', 'Besok hasil pemeriksaan kemungkinan akan keluar.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7125, 3222, 'これは先生が査読した論文です。', 'Kore wa sensei ga sadoku shita ronbun desu.', 'Ini adalah makalah yang telah ditelaah oleh guru.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7126, 3223, '父は実業をしているんです。', 'Chichi wa jitsugyou wo shite iru n desu.', 'Ayah saya menjalankan bisnis/dunia usaha.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7127, 3223, 'この計画は実現できるでしょう。', 'Kono keikaku wa jitsugen dekiru deshou.', 'Rencana ini kemungkinan bisa diwujudkan.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7128, 3223, '実験の前に、色々な物をじゅんびしておきます。', 'Jikken no mae ni, iroiro na mono wo junbi shite okimasu.', 'Sebelum eksperimen, persiapkan berbagai macam hal terlebih dahulu.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7129, 3223, 'ビデオを見せながら、実話を話します。', 'Bideo wo misenagara, jitsuwa wo hanashimasu.', 'Sambil memperlihatkan video, saya menceritakan kisah nyata.', false);
INSERT INTO `ExampleSentence` (`id`, `kanjiId`, `japanese`, `romaji`, `translation`, `isReading`) VALUES (7130, 3223, '私は、もっと実習が必要だと思います。', 'Watashi wa, motto jisshuu ga hitsuyou da to omoimasu.', 'Menurut saya, diperlukan lebih banyak praktik.', false);
