INSERT INTO `Quiz` (`id`, `kanjiId`, `type`, `question`, `options`, `correctAnswer`, `words`, `correctOrder`, `targetWord`, `leftItems`, `rightItems`, `pairs`, `groups`, `explanation`) VALUES (4938, 3223, 'grouping', 'Kelompokkan jukugo berikut ini ke dalam cabang semantic graph kanji 実 yang tepat.', NULL, NULL, '["事実","真実","実話","実感","口実","実験","実習","実演","実戦","実現","実用","実収","確実","着実","実測","実質","実家","実業","実直","内実"]', NULL, NULL, NULL, NULL, NULL, '[{"Fakta dan Kenyataan":["事実","真実","実話","実感","口実"]},{"Praktik dan Pelaksanaan":["実験","実習","実演","実戦"]},{"Hasil dan Perwujudan":["実現","実用","実収"]},{"Ketepatan dan Kepastian":["確実","着実","実測","実質"]},{"Kehidupan Nyata":["実家","実業","実直","内実"]}]', 'Pengelompokan jukugo berdasarkan 5 cabang semantic graph kanji 実.');
INSERT INTO `Quiz` (`id`, `kanjiId`, `type`, `question`, `options`, `correctAnswer`, `words`, `correctOrder`, `targetWord`, `leftItems`, `rightItems`, `pairs`, `groups`, `explanation`) VALUES (4939, 3223, 'multiple', 'Jukugo mana yang berhubungan dengan makna "sesuatu yang benar-benar terjadi"?', '["実話","実験","実家","実測"]', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Jawaban tepat: a. 実話');
INSERT INTO `Quiz` (`id`, `kanjiId`, `type`, `question`, `options`, `correctAnswer`, `words`, `correctOrder`, `targetWord`, `leftItems`, `rightItems`, `pairs`, `groups`, `explanation`) VALUES (4940, 3223, 'multiple', 'Jukugo mana yang berhubungan dengan makna "kegiatan melakukan percobaan untuk membuktikan sebuah teori"?', '["実感","実験","実現","実業"]', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Jawaban tepat: b. 実験');
INSERT INTO `Quiz` (`id`, `kanjiId`, `type`, `question`, `options`, `correctAnswer`, `words`, `correctOrder`, `targetWord`, `leftItems`, `rightItems`, `pairs`, `groups`, `explanation`) VALUES (4941, 3223, 'multiple', 'Jukugo mana yang berhubungan dengan makna "mengubah rencana atau harapan menjadi kenyataan"?', '["実質","実用","実現","内実"]', '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Jawaban tepat: c. 実現');
INSERT INTO `Quiz` (`id`, `kanjiId`, `type`, `question`, `options`, `correctAnswer`, `words`, `correctOrder`, `targetWord`, `leftItems`, `rightItems`, `pairs`, `groups`, `explanation`) VALUES (4942, 3223, 'multiple', 'Jukugo mana yang berhubungan dengan makna “sesuatu yang dapat digunakan secara praktis dalam kehidupan sehari-hari”?', '["実用","実直","実話","実家"]', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Jawaban tepat: a. 実用');
